page.css:
/* Korean Engine Specialist - global header, sidebar and top bar */
*{margin:0;padding:0;box-sizing:border-box}
:root{
 --ink:#070a0e; --ink2:#0d1319; --char:#121c25; --char2:#18242e; --char3:#1f2f3b;
 --blue:#0a63f5; --blue-l:#4f94ff; --blue-d:#0a3fb0;
 --red:#e21019; --red-l:#ff2a31; --red-d:#a80a11;
 --paper:#f4f7f9; --paper2:#e9eef2; --white:#fff;
 --tx:#15202a; --tx2:#55646f; --line:#e1e8ed; --line-d:#243440;
 --gut:clamp(18px,5vw,56px); --rad:14px; --maxw:1280px; --utilh:44px;
 --sh:0 14px 36px -16px rgba(9,15,20,.26); --sh2:0 34px 78px -30px rgba(9,15,20,.55);
 --fd:'Archivo',system-ui,sans-serif; --fb:'Inter',system-ui,sans-serif;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--fb);color:var(--tx);background:var(--ink);line-height:1.6;overflow-x:hidden}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
p{overflow-wrap:anywhere}
select option{background:#0d1319;color:#fff}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut);width:100%}
.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;border-radius:10px;padding:16px 28px;font-size:15px;letter-spacing:.03em;cursor:pointer;transition:.22s;border:0;white-space:nowrap;position:relative;overflow:hidden;text-transform:uppercase}
.btn svg{width:17px;height:17px}
.btn::after{content:"";position:absolute;top:0;left:-130%;width:55%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.4),transparent);transform:skewX(-18deg);transition:left .65s ease}
.btn:hover::after{left:170%}
.btn-r{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;box-shadow:0 16px 32px -12px rgba(226,16,25,.75)}
.btn-r:hover{transform:translateY(-3px);box-shadow:0 22px 44px -12px rgba(226,16,25,.9)}
@keyframes spin{to{transform:rotate(360deg)}}
@property --q1{syntax:'<integer>';initial-value:0;inherits:false}
@property --q2{syntax:'<integer>';initial-value:0;inherits:false}
@property --q3{syntax:'<integer>';initial-value:0;inherits:false}
@property --q4{syntax:'<integer>';initial-value:0;inherits:false}
@keyframes spark{0%,100%{opacity:.35;transform:translateX(-50%) scale(.75)}50%{opacity:1;transform:translateX(-50%) scale(1.15)}}
@keyframes nudge{0%,100%{transform:translateX(0)}50%{transform:translateX(-5px)}}
@media(max-width:560px){
.btn{white-space:normal;text-align:center;line-height:1.25;padding:15px 20px;justify-content:center}
}
@media (prefers-reduced-motion:reduce){
*{scroll-behavior:auto!important}
}
:root{--steel:#1b2631;--steel2:#243240;--steel3:#2d3e4d;--bolt:#8ea2b2}
.tex{position:relative}
.tex::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;opacity:.5;
 background-image:
  linear-gradient(45deg,rgba(255,255,255,.04) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.04) 75%),
  linear-gradient(45deg,rgba(255,255,255,.04) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.04) 75%);
 background-size:16px 16px;background-position:0 0,8px 8px}
.tex>*{position:relative;z-index:1}
.hz{height:7px;background:repeating-linear-gradient(135deg,var(--red) 0 11px,#0d141b 11px 22px);opacity:.9}
.cog{position:absolute;pointer-events:none;z-index:0;color:rgba(255,255,255,.05);animation:spin 34s linear infinite}
.cog.ccw{animation-direction:reverse}
.cog svg{width:100%;height:auto}
.btn-r{border-top:1px solid rgba(255,255,255,.3);border-bottom:1px solid rgba(0,0,0,.35)}
@keyframes wrench{0%,62%,100%{transform:rotate(0)}72%{transform:rotate(-26deg)}82%{transform:rotate(6deg)}}
@keyframes gauge{from{transform:scaleX(.04)}to{transform:scaleX(1)}}
@keyframes led{0%{box-shadow:0 0 0 0 rgba(255,42,49,.75)}70%{box-shadow:0 0 0 10px rgba(255,42,49,0)}100%{box-shadow:0 0 0 0 rgba(255,42,49,0)}}
html{background:var(--ink)}
@keyframes paneIn{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}
.btn-ghd{background:#fff;color:var(--tx2);border:1.5px solid var(--line);box-shadow:none}
.btn-ghd:hover{background:#f3f7fa;border-color:#c6d2db;color:var(--ink);transform:translateY(-2px)}
.ab-list,.ty-steps,.ulq,.regs,.cov,.cons-rows,.foot-ul,.stp,.tree,.sh-chips{margin-left:0;padding-left:0}
.util{background:var(--ink);color:#93a4b1;font-size:13px;border-bottom:1px solid rgba(255,255,255,.07);height:var(--utilh);overflow:hidden}
.util-in{display:flex;align-items:center;justify-content:space-between;gap:14px;height:var(--utilh);flex-wrap:nowrap;overflow:hidden}
.util .u-l{display:flex;gap:22px;align-items:center;flex-wrap:wrap}
.util .ui{display:inline-flex;align-items:center;gap:7px}
.util svg{width:15px;height:15px;color:var(--red-l)}
.util a{color:#cfdae2;font-weight:600}
.util a:hover{color:var(--red-l)}
.util .u-r{color:#7d8e9b;font-weight:600;letter-spacing:.04em;text-transform:uppercase;font-size:11.5px}
header{position:sticky;top:calc(0px - var(--utilh));z-index:95;background:transparent;border:0;margin:0}
.kes-header,.kes-footer,.kes-page{margin:0}
.hdr-bar{background:#070a0e;border-bottom:1px solid rgba(255,255,255,.08)}
.hdr-in{display:flex;align-items:center;gap:clamp(12px,1.6vw,22px);min-height:80px;min-width:0}
.brand{flex-shrink:0;display:block;line-height:0}
.brand img{height:42px;width:auto;max-width:none}
.nav{display:flex;align-items:center;gap:clamp(10px,1.35vw,19px);margin-left:auto;min-width:0;flex-wrap:nowrap}
.nav a.nl{font-weight:600;font-size:clamp(13px,1.02vw,14.5px);color:#d8e0e7;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;padding:6px 0;position:relative}
.nav a.nl .ca{width:13px;height:13px;color:#86949f}
.nav a.nl::after{content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:.25s}
.nav a.nl:hover{color:#fff}
.nav a.nl:hover::after{transform:scaleX(1)}
.hdr-cta{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;flex:0 0 auto;background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;font-weight:800;font-family:var(--fd);padding:13px clamp(14px,1.4vw,20px);border-radius:9px;font-size:13.5px;letter-spacing:.05em;text-transform:uppercase;box-shadow:0 12px 24px -12px rgba(226,16,25,.8);transition:.2s;cursor:pointer}
.hdr-cta:hover{transform:translateY(-2px)}
.nd{position:relative;display:flex;align-items:center}
.nd>.nl-p{cursor:pointer}
.nl-p .ca{width:12px;height:12px;color:#86949f;transition:transform .2s}
.nd:hover>.nl-p .ca,.nd:focus-within>.nl-p .ca{transform:rotate(180deg);color:#fff}
.nmenu{position:absolute;top:100%;left:-16px;margin-top:14px;min-width:244px;
 background:linear-gradient(180deg,#0e161e,#0a1016);border:1px solid rgba(255,255,255,.13);
 border-radius:14px;padding:16px;box-shadow:0 30px 60px -22px rgba(0,0,0,.9),0 0 0 1px rgba(0,0,0,.4);
 opacity:0;visibility:hidden;transform:translateY(9px);transition:opacity .18s,transform .18s,visibility .18s;z-index:70}
.nmenu::before{content:"";position:absolute;left:0;right:0;top:-16px;height:16px}
.nmenu::after{content:"";position:absolute;left:30px;top:-6px;width:11px;height:11px;
 background:#0e161e;border-left:1px solid rgba(255,255,255,.13);border-top:1px solid rgba(255,255,255,.13);transform:rotate(45deg)}
.nmenu.r{left:auto;right:-16px}
.nmenu.r::after{left:auto;right:30px}
.nd:hover>.nmenu,.nd:focus-within>.nmenu{opacity:1;visibility:visible;transform:none}
.nmenu.mega{display:grid;grid-template-columns:repeat(2,minmax(166px,1fr));gap:4px 22px;min-width:392px}
.nmenu.mega-3{grid-template-columns:repeat(3,minmax(150px,1fr));min-width:534px}
.nmc{display:flex;flex-direction:column;min-width:0}
.nmh{font-family:var(--fd);font-weight:800;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;
 color:var(--red-l);padding:4px 10px 8px}
.nmenu a{display:block;padding:8px 10px;border-radius:8px;font-size:14px;font-weight:600;color:#cfdae2;
 white-space:nowrap;transition:background .15s,color .15s}
.nmenu a:hover,.nmenu a:focus-visible{background:rgba(255,255,255,.08);color:#fff}
.nmenu .nma{grid-column:1/-1;margin-top:10px;padding-top:12px;border-top:1px solid rgba(255,255,255,.1);
 display:inline-flex;align-items:center;gap:8px;font-family:var(--fd);font-weight:800;font-size:12.5px;
 letter-spacing:.05em;text-transform:uppercase;color:var(--red-l);border-radius:0}
.nmenu .nma svg{width:15px;height:15px;transition:transform .2s}
.nmenu .nma:hover{background:transparent;color:#fff}
.nmenu .nma:hover svg{transform:translateX(4px)}
@media (prefers-reduced-motion:reduce){
.nmenu{transition:none}
}
.hdr-cta svg{width:15px;height:15px}
.burger{display:none;width:46px;height:46px;border:1px solid rgba(255,255,255,.2);border-radius:10px;cursor:pointer;align-items:center;justify-content:center;background:rgba(255,255,255,.05);margin-left:auto}
.burger span,.burger span::before,.burger span::after{content:"";position:absolute;width:22px;height:2.4px;background:#eef3f8;border-radius:2px;transition:.25s}
.burger span{position:relative}
.burger span::before{top:-7px}
.burger span::after{top:7px}
.m-ph{display:none}
.sc-b{padding:28px 26px 30px;width:100%}
.sc-n{font-family:var(--fd);font-weight:900;font-size:40px;color:rgba(255,255,255,.22);line-height:1;letter-spacing:-.04em}
.sc-b h3{font-size:22px;color:#fff;margin-top:10px;text-transform:uppercase}
.sc-b p{font-size:14.5px;color:#c3d0d8;margin-top:12px;max-height:0;opacity:0;overflow:hidden;transition:.4s}
.sc-b .more{display:inline-flex;align-items:center;gap:8px;margin-top:18px;color:#fff;font-weight:800;font-family:var(--fd);font-size:12px;letter-spacing:.1em;text-transform:uppercase;cursor:pointer}
.sc-b .more i{width:34px;height:34px;border-radius:50%;background:var(--red);display:grid;place-items:center;transition:.25s}
.sc-b .more i svg{width:15px;height:15px}
.sq-ov{position:fixed;inset:0;background:rgba(4,7,10,.74);backdrop-filter:blur(4px);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s;z-index:88;cursor:pointer}
#sideq:checked ~ .sq-ov{opacity:1;visibility:visible}
.sq-panel{position:fixed;right:0;top:0;height:100%;z-index:90;width:min(442px,100%);background:var(--paper);box-shadow:-30px 0 80px -24px rgba(4,7,10,.7);transform:translateX(100%);visibility:hidden;transition:transform .42s cubic-bezier(.4,0,.1,1),visibility .42s;overflow-y:auto;overscroll-behavior:contain}
#sideq:checked ~ .sq-panel{transform:translateX(0);visibility:visible}
.sq-close{position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);color:#fff;display:grid;place-items:center;cursor:pointer;z-index:3;transition:.2s}
.sq-close:hover{background:var(--red);border-color:var(--red);transform:rotate(90deg)}
.sq-close svg{width:16px;height:16px}
.sq-head{position:relative;background:radial-gradient(120% 130% at 100% 0%,#152029,var(--ink));color:#fff;padding:26px 24px 24px;overflow:hidden}
.sq-head::after{content:"";position:absolute;right:-50px;top:-50px;width:190px;height:190px;border-radius:50%;background:radial-gradient(circle,rgba(226,16,25,.34),transparent 68%)}
.sq-head-in{position:relative;z-index:2;display:flex;align-items:center;gap:14px}
.sq-head-ic{width:56px;height:56px;border-radius:14px;background:rgba(226,16,25,.16);border:1px solid rgba(226,16,25,.4);display:grid;place-items:center;flex-shrink:0}
.sq-head-ic svg{width:30px;height:30px;color:var(--red-l);animation:spin 9s linear infinite}
.sq-kick{display:inline-block;font-family:var(--fd);font-weight:800;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--red-l);margin-bottom:8px}
.sq-head h3{font-size:22px;text-transform:uppercase;line-height:1.05}
.sq-head p{font-size:13.5px;color:#a9b9c3;margin-top:12px;position:relative;z-index:2}
.sq-strip{display:flex;gap:8px;flex-wrap:wrap;padding:14px 24px;background:var(--ink2);border-bottom:1px solid rgba(255,255,255,.07)}
.sq-strip span{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;color:#bdcad3;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);padding:6px 11px;border-radius:999px}
.sq-strip svg{width:13px;height:13px;color:var(--red-l)}
.sq-form{display:grid;gap:12px;padding:22px 24px 26px}
.sq-l{font-size:12px;font-weight:700;color:var(--tx2);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px;display:block}
.sq-f{min-width:0}
.sq-f input,.sq-f select,.sq-f textarea{min-width:0;width:100%;font:inherit;font-size:15px;padding:13px 14px;border:1.5px solid var(--line);border-radius:10px;background:#fff;color:var(--tx);appearance:none;transition:.2s}
.sq-f select{background-image:linear-gradient(45deg,transparent 50%,#55646f 50%),linear-gradient(135deg,#55646f 50%,transparent 50%);background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;background-size:6px 6px,6px 6px;background-repeat:no-repeat}
.sq-f select option{background:#fff;color:var(--tx)}
.sq-f input:focus,.sq-f select:focus,.sq-f textarea:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px rgba(226,16,25,.14)}
.sq-f textarea{resize:vertical;min-height:76px}
.sq-2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.sq-2>*{min-width:0}
.sq-form .sq-sub{width:100%;justify-content:center;margin-top:4px}
.sq-fine{font-size:11.5px;color:var(--tx2);display:flex;align-items:center;justify-content:center;gap:6px;margin-top:4px}
.sq-fine svg{width:14px;height:14px;color:var(--red)}
.sq-foot{background:var(--ink);color:#a9b9c3;padding:20px 24px 26px;margin-top:auto}
.sq-foot small{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:#7d8e9b;margin-bottom:8px}
.sq-foot a.sq-ph{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:900;font-size:23px;color:#fff}
.sq-foot a.sq-ph svg{width:20px;height:20px;color:var(--red-l)}
.sq-foot p{font-size:12.5px;margin-top:10px;color:#7d8e9b}
.mbar{display:none;position:fixed;left:0;right:0;bottom:0;z-index:70;background:rgba(7,10,14,.97);border-top:1px solid var(--line-d);padding:9px 12px;gap:10px}
.mbar a,.mbar label{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--fd);font-weight:800;font-size:14px;padding:13px;border-radius:10px;cursor:pointer;text-transform:uppercase;letter-spacing:.03em}
.mbar .m-call{background:var(--char3);color:#fff}
.mbar .m-quote{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff}
.mbar svg{width:17px;height:17px}
@media(min-width:1281px){
.hdr-bar{overflow-x:clip}
}
@media(max-width:1280px){
.nav{position:fixed;top:0;right:0;height:100vh;height:100dvh;width:min(338px,86vw);background:#0a0e13;flex-direction:column;align-items:stretch;gap:0;padding:92px 26px 30px;margin:0;box-shadow:var(--sh2);clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .3s;overflow-y:auto;z-index:62}
.nav a.nl{padding:15px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:16px;color:#e7edf3}
.nav .hdr-cta{margin-top:20px;justify-content:center}
.nav .m-ph{display:inline-flex;align-items:center;justify-content:center;gap:8px;margin-top:16px;font-family:var(--fd);font-weight:800;font-size:18px;color:#eef3f8}
.nav .m-ph svg{width:18px;height:18px;color:var(--red-l)}
.nd{display:block}
.nd>.nl-p{display:flex;justify-content:space-between;width:100%}
.nd>.nl-p .ca{width:15px;height:15px}
.nmenu{position:static;opacity:1;visibility:visible;transform:none;margin:0 0 6px;padding:2px 0 10px 14px;
  min-width:0;background:none;border:0;border-radius:0;box-shadow:none;display:block}
.nmenu.mega,.nmenu.mega-3{display:block;min-width:0}
.nmenu::before,.nmenu::after{display:none}
.nmenu a{padding:9px 0;font-size:14.5px;border-radius:0;white-space:normal}
.nmh{padding:10px 0 2px}
.nmenu .nma{margin-top:6px;padding-top:10px}
#mtog:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
#mtog:checked ~ .burger span{background:transparent}
#mtog:checked ~ .burger span::before{top:0;transform:rotate(45deg)}
#mtog:checked ~ .burger span::after{top:0;transform:rotate(-45deg)}
.burger{display:inline-flex;position:relative;z-index:63}
}
@media(max-width:900px){
.util .u-r{display:none}
.util-in{justify-content:center}
.util .u-l{gap:16px}
.util .u-l>*:not(.u-keep):not(:first-child){display:none}
}
@media(max-width:720px){
.util .u-r{display:none}
.util-in{justify-content:center}
.util .u-l>*:not(.u-keep){display:none}
.sc-b p{max-height:140px;opacity:1}
.mbar{display:flex}
.sq-tab{display:none}
.sq-panel{width:100%}
}
@media(max-width:460px){
.brand img{height:32px}
.sq-2{grid-template-columns:minmax(0,1fr)}
}
@media (prefers-reduced-motion:reduce){
.rv,.grad,.blob,.pbeat::before,.sq-tab-ar,.sq-tab-ic::after,.hvis-rt,.hero-bg,.spin-r,.ab-gear,.sq-head-ic svg,.eyb::before,.ab-ph .ph-ic,.btn::after{animation:none!important}
}
.rail{height:14px;background:linear-gradient(180deg,#141d26,#0a1017);border-bottom:1px solid #22313e;
 background-image:radial-gradient(circle at 16px 7px,#6d8395 0 1.8px,transparent 2px);
 background-size:52px 14px;background-repeat:repeat-x}
.sq-rail{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:86;display:flex;align-items:center;transition:transform .35s,opacity .25s}
#sideq:checked ~ .sq-rail{transform:translateY(-50%) translateX(130%);opacity:0;pointer-events:none}
.sq-trust{position:absolute;right:66px;top:50%;transform:translateY(-50%) translateX(26px);
 width:238px;padding:20px 18px 18px;border-radius:16px;
 background-color:#10181f;background-image:radial-gradient(circle at 11px 11px,#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),radial-gradient(circle at calc(100% - 11px) 11px,#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),radial-gradient(circle at 11px calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),radial-gradient(circle at calc(100% - 11px) calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),linear-gradient(165deg,#1d2831,#10181f 60%,#0b1117);
 background-repeat:no-repeat;border:1px solid #2d3d4b;
 box-shadow:-22px 22px 54px -18px rgba(0,0,0,.8);
 opacity:0;visibility:hidden;transition:transform .4s cubic-bezier(.3,0,.2,1),opacity .3s,visibility .4s;
 display:grid;gap:16px}
.sq-rail:hover .sq-trust,.sq-rail:focus-within .sq-trust{opacity:1;visibility:visible;transform:translateY(-50%) translateX(0)}
.sq-tr{text-align:center}
.sq-tr-ic{width:40px;height:40px;margin:0 auto 9px;border-radius:11px;background:rgba(226,16,25,.14);border:1px solid rgba(226,16,25,.4);display:grid;place-items:center}
.sq-tr-ic svg{width:21px;height:21px;color:var(--red-l)}
.sq-tr b{display:block;font-family:var(--fd);font-weight:800;font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:#fff;line-height:1.45}
.sq-tr i{display:block;font-style:normal;font-size:11px;color:#8da0ad;letter-spacing:.04em;margin-top:3px;text-transform:uppercase;font-weight:700}
.sq-trust-hz{height:6px;border-radius:3px;background:repeating-linear-gradient(135deg,var(--red) 0 9px,transparent 9px 18px);opacity:.7}
.sq-tab{position:relative;width:66px;cursor:pointer;border-radius:16px 0 0 16px;
 background:linear-gradient(170deg,#28363f,#141e27 58%,#0c131a);border:1px solid #425666;border-right:0;
 box-shadow:-12px 16px 38px -14px rgba(0,0,0,.75);
 display:flex;flex-direction:column;align-items:center;padding:34px 0 0;transition:.28s}
