 --gut:clamp(18px,5vw,56px); --rad:14px; --maxw:1280px; --utilh:44px;
 --sh:0 14px 36px -16px rgba(9,15,20,.26); --sh2:0 34px 78px -30px rgba(9,15,20,.55);
 --fd:'Archivo',system-ui,sans-serif; --fb:'Inter',system-ui,sans-serif;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--fb);color:var(--tx);background:var(--ink);line-height:1.6;overflow-x:hidden}
